parameters.jsCode:
// Turns Claude's structured assessment into the JSON reply, a Markdown report and a flat sheet row
const req = $('Read the request').item.json;
const out = $json.output;
const DIMENSIONS = [
  ['confidentiality', 'Confidentiality'],
  ['integrity', 'Integrity'],
  ['availability', 'Availability'],
  ['compliance', 'Compliance'],
  ['operational', 'Operational'],
];

const base = {
  system_name: req.system_name,
  industry: req.industry,
  scenario: req.scenario,
  generated_at: req.generated_at,
};

if (!out || typeof out !== 'object' || !out.dimensions) {
  return {
    json: {
      ...base,
      status: 'error',
      http_code: 500,
      message: 'The assessment could not be generated. Check the Anthropic credential and the execution log, then try again.',
      overall_rating: 'Unrated',
      ratings: {},
    },
  };
}

const ratings = {};
const sections = DIMENSIONS.map(([key, label], i) => {
  const d = out.dimensions[key] || {};
  ratings[key] = d.level || 'Unrated';
  return [
    `## ${i + 1}. ${label} risk: ${ratings[key]}`,
    d.description || '',
    `**Mitigation:** ${d.mitigation || 'None given'}`,
    `**Reference:** ${d.reference || 'None given'}`,
  ].join('\n\n');
});

const assumptions = Array.isArray(out.assumptions) ? out.assumptions : [];
const markdown = [
  `# IS risk assessment: ${req.system_name}`,
  `**Industry:** ${req.industry}  \n**Overall risk rating:** ${out.overall_rating}  \n**Generated:** ${req.generated_at}`,
  `## Executive summary\n\n${out.executive_summary || ''}`,
  ...sections,
  assumptions.length ? `## Assumptions\n\n${assumptions.map(a => `- ${a}`).join('\n')}` : '',
].filter(Boolean).join('\n\n');

return {
  json: {
    ...base,
    status: 'success',
    http_code: 200,
    overall_rating: out.overall_rating || 'Unrated',
    ratings,
    dimensions: out.dimensions,
    executive_summary: out.executive_summary || '',
    assumptions,
    report_markdown: markdown,
  },
};

